{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.marketplace_sales_returns as ( with sales_data_pre as ( select case when lower(\"Channel Ledger\") like \'%myntra%\' then \'myntra\' when lower(\"Channel Ledger\") like \'%amazon%\' then \'amazon\' when lower(\"Channel Ledger\") like \'%ajio%\' then \'ajio\' when lower(\"Channel Ledger\") like \'%flipkart%\' then \'flipkart\' end as marketplace, \"Sale Order Number\"::varchar as order_name, TO_DATE(\"Original Invoice Date \" , \'DD-MM-YYYY\') as order_date, \"Product Name\" as product_name, \"Product SKU Code\" as sku, qty as quantity_sold, case when entity = \'CAN_INVOICE\' then qty else 0 end as cancel_qty, sales as gross_sales, total as gross_sales_post_gst, \"Unit Price\" as selling_price, \"Discount Amount\" as discount_amount from snitch_db.maplemonk.S3_MP_UNIWARE_SALES_FOR_RETURNS ), price as ( SELECT VARIANT.value:sku::STRING as sku, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku)) as sku, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price ), final_price_adj as ( select sku, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), final_price as ( select sku, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), sales_data as ( select a.*, b.original_price, a.quantity_sold*b.original_price as expected_gross_sales, (a.quantity_sold*b.original_price)- a.gross_sales as real_discount_amount from sales_data_pre a left join final_price b on a.sku = b.sku ), ajio_returns as ( select \'ajio\' as marketplace, \"FWD PO No\"::varchar as order_name, case when left(\"SELLER SKU\",4) = \'Four\' then REPLACE(\"SELLER SKU\", \'Four\', \'4\') else \"SELLER SKU\" end as sku, \"Return QTY\"::int as return_qty, \"Cust Return Reason\"::varchar as return_reason, \"3PL Delivery Status\"::varchar as warehouse_return_status, case when \"Return Type\" = \'RVP\' then \'dto\' else \"Return Type\"::varchar end as return_type from snitch_db.maplemonk.S3_AJIO_RETURNS where \"Return QTY\"::int != 0 and \"Return QTY\" != \'\' ), myntra_returns as ( select \'myntra\' as marketplace, seller_order_id::varchar as order_name, case when left(seller_sku_code,4) = \'Four\' then REPLACE(seller_sku_code, \'Four\', \'4\') else seller_sku_code end as sku, quantity as return_qty, return_reason as return_reason, status as warehouse_return_status, case when type = \'Return\' then \'dto\' else \'rto\' end as return_type from snitch_db.maplemonk.S3_MYNTRA_RETURNS where quantity != 0 and quantity != \'\' ), flipkart_returns as ( select \'flipkart\' as marketplace, \"Order ID\"::varchar as order_name, case when left(sku,4) = \'Four\' then REPLACE(sku, \'Four\', \'4\') else sku end as sku, quantity as return_qty, \"Return Reason\" as return_reason, \"Return Status\" as warehouse_return_status, case when \"Return Type\" = \'courier_return\' then \'rto\' else \'dto\' end as return_type from snitch_db.maplemonk.S3_FLIPKART_RETURNS_POD where \"Return Status\" != \'seller_rejected\' and quantity != 0 and quantity != \'\' ), amazon_returns as ( select \'amazon\' as marketplace, \"Display Order Number\"::varchar as order_name, \"Product SKU Code\" as sku, qty as return_qty, \'none\' as return_reason, \'all deleivered\' as warehouse_return_status, case when \"Return Type\" = \'CIR\' then \'dto\' else \'rto\' end as return_type from snitch_db.maplemonk.S3_AMAZON_RETURNS_UNIWARE where qty != 0 and qty != \'\' ), overall_returns as ( select * from ajio_returns union all select * from myntra_returns union all select * from flipkart_returns union all select * from amazon_returns ), product_images as ( SELECT DISTINCT id, REPLACE(A.value:src,\'\"\',\'\') AS src, REPLACE(A.value:position,\'\"\',\'\') AS pst FROM snitch_db.maplemonk.shopifyindia_new_products, LATERAL FLATTEN(INPUT => IMAGES) A WHERE pst = 1 ), final_images as ( select b.sku_group, a.src as image_link, row_number() over (partition by b.sku_group order by a.id desc) as rn from product_images a left join snitch_db.maplemonk.availability_master_v2 b on a.id = b.id ), main_data as ( select a.*, coalesce(b.return_qty,0) as return_qty, SPLIT_PART(a.sku, \'-\', -1) AS size, REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) AS sku_group, b.return_qty*a.gross_sales_post_gst as return_amount, b.return_reason, b.warehouse_return_status, b.return_type, f.category, c.color, c.fit, c.material, d.sellable_inventory as inventory, e.image_link, g.product_tags from sales_data a left join overall_returns b on a.marketplace = b.marketplace and a.order_name = b.order_name and a.sku = b.sku left join snitch_db.maplemonk.metafields_data c on REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) = c.sku_group left join snitch_db.maplemonk.availability_master_v2 d on REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) = d.sku_group left join final_images e on REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) = e.sku_group left join snitch_db.maplemonk.availability_master_v2 f on REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) = f.sku_group left join snitch_db.maplemonk.product_journey g on REVERSE(SUBSTRING(REVERSE(a.sku), CHARINDEX(\'-\', REVERSE(a.sku)) + 1, LEN(a.sku))) = g.sku_group where e.rn = 1 order by order_date asc ) select a.*,c2 as return_reason_mapping from main_data a left join SNITCH_DB.MAPLEMONK.MARKETPLACE_RETURNS_MAPPING b on a.return_reason = b.c1 )",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            